// Typed wrapper around rc_core.wasm: copies arrays to the wasm heap, calls
// the kernel and copies the result back. Matrices are column-major (n x k),
// like R, so the C++ is a literal port of rc2.
// @ts-ignore: generated by scripts/build-wasm.mjs
import createRcCore from './wasm/rc_core.js';

interface RcModule {
  HEAPF64: Float64Array;
  HEAP32: Int32Array;
  _rc_alloc(bytes: number): number;
  _rc_free(ptr: number): void;
  _rc_smoke(): number;
  _rc_topology(...a: number[]): number;
  _rc_chains(...a: number[]): void;
  _rc_strahler(...a: number[]): void;
  _rc_dp_mult(...a: number[]): void;
  _rc_loo_mult(...a: number[]): void;
  _rc_bounded(...a: number[]): void;
}

export interface Topology {
  parent: Int32Array;
  order: Int32Array;
  childPtr: Int32Array;
  childIdx: Int32Array;
  rootOf: Int32Array;
  depth: Int32Array;
  nReached: number;
}

export interface DpResult {
  sTo: Float64Array;
  sFrom: Float64Array;
  din?: Float64Array;
  dout?: Float64Array;
  uin?: Float64Array;
  uout?: Float64Array;
}

export const KERNEL = { thresholdSym: 1, thresholdAsym: 2, leptokurtic: 3 } as const;
export const BOUNDED_BLOCK = 256;

type Arr = Float64Array | Int32Array;

export class RcCore {
  private constructor(private m: RcModule) {}

  static async create(): Promise<RcCore> {
    return new RcCore((await createRcCore()) as RcModule);
  }

  smoke(): number {
    return this.m._rc_smoke();
  }

  // Runs `fn` with the given arrays copied to the heap (pointers in order)
  // plus `outs` zero-initialised output buffers; returns the outputs.
  private call(
    ins: Arr[],
    outs: { type: 'f64' | 'i32'; len: number }[],
    fn: (inPtrs: number[], outPtrs: number[]) => number | void,
  ): { ret: number | void; outs: Arr[] } {
    const m = this.m;
    const ptrs: number[] = [];
    const alloc = (bytes: number) => {
      const p = m._rc_alloc(Math.max(bytes, 8));
      if (!p) throw new Error('wasm out of memory');
      ptrs.push(p);
      return p;
    };
    try {
      const inPtrs = ins.map((a) => {
        const p = alloc(a.byteLength);
        if (a instanceof Float64Array) m.HEAPF64.set(a, p / 8);
        else m.HEAP32.set(a, p / 4);
        return p;
      });
      const outPtrs = outs.map((o) => {
        const p = alloc(o.len * (o.type === 'f64' ? 8 : 4));
        (o.type === 'f64' ? m.HEAPF64.fill(0, p / 8, p / 8 + o.len) : m.HEAP32.fill(0, p / 4, p / 4 + o.len));
        return p;
      });
      const ret = fn(inPtrs, outPtrs);
      // heap views may have been replaced if memory grew: read them fresh
      const res = outs.map((o, i) =>
        o.type === 'f64'
          ? this.m.HEAPF64.slice(outPtrs[i] / 8, outPtrs[i] / 8 + o.len)
          : this.m.HEAP32.slice(outPtrs[i] / 4, outPtrs[i] / 4 + o.len),
      );
      return { ret, outs: res };
    } finally {
      for (const p of ptrs) m._rc_free(p);
    }
  }

  /** Rooted-forest topology from 0-based parent indices (-1 for outlets). */
  topology(parent: Int32Array): Topology {
    const n = parent.length;
    const { ret, outs } = this.call(
      [parent],
      [
        { type: 'i32', len: n },
        { type: 'i32', len: n + 1 },
        { type: 'i32', len: n },
        { type: 'i32', len: n },
        { type: 'i32', len: n },
        { type: 'i32', len: 1 },
      ],
      ([p], [order, cptr, cidx, root, depth, err]) =>
        this.m._rc_topology(p, n, order, cptr, cidx, root, depth, err),
    );
    const nReached = ret as number;
    if (nReached === -1) throw new Error(`invalid parent index at node ${(outs[5] as Int32Array)[0] + 1}`);
    if (nReached === -2) throw new Error(`node ${(outs[5] as Int32Array)[0] + 1} is its own parent`);
    return {
      parent,
      order: outs[0] as Int32Array,
      childPtr: outs[1] as Int32Array,
      childIdx: outs[2] as Int32Array,
      rootOf: outs[3] as Int32Array,
      depth: outs[4] as Int32Array,
      nReached,
    };
  }

  /** Unbranched chains: chain head and position along the chain. */
  chains(t: Topology): { chain: Int32Array; pos: Int32Array } {
    const n = t.parent.length;
    const { outs } = this.call(
      [t.parent, t.order, t.childPtr],
      [
        { type: 'i32', len: n },
        { type: 'i32', len: n },
      ],
      ([p, o, c], [chain, pos]) => this.m._rc_chains(p, o, c, n, chain, pos),
    );
    return { chain: outs[0] as Int32Array, pos: outs[1] as Int32Array };
  }

  /** Strahler stream order; -1 for nodes not reached from a root. */
  strahler(t: Topology): Int32Array {
    const n = t.parent.length;
    const { outs } = this.call(
      [t.order, t.childPtr, t.childIdx],
      [{ type: 'i32', len: n }],
      ([o, c, i], [so]) => this.m._rc_strahler(o, c, i, n, t.nReached, so),
    );
    return outs[0] as Int32Array;
  }

  /** Linear-time reach sums for multiplicative kernels; W is n x k. */
  dpMult(t: Topology, fu: Float64Array, fd: Float64Array, W: Float64Array, k: number, keep = false): DpResult {
    const n = t.parent.length;
    const nk = n * k;
    const kk = keep ? nk : 0;
    const { outs } = this.call(
      [t.parent, t.order, t.childPtr, t.childIdx, fu, fd, W],
      [
        { type: 'f64', len: nk },
        { type: 'f64', len: nk },
        { type: 'f64', len: kk },
        { type: 'f64', len: kk },
        { type: 'f64', len: kk },
        { type: 'f64', len: kk },
      ],
      ([p, o, cp, ci, fup, fdp, w], [sTo, sFrom, din, dout, uin, uout]) =>
        this.m._rc_dp_mult(p, o, cp, ci, fup, fdp, w, n, k, keep ? 1 : 0, sTo, sFrom, din, dout, uin, uout),
    );
    const res: DpResult = { sTo: outs[0] as Float64Array, sFrom: outs[1] as Float64Array };
    if (keep) {
      res.din = outs[2] as Float64Array;
      res.dout = outs[3] as Float64Array;
      res.uin = outs[4] as Float64Array;
      res.uout = outs[5] as Float64Array;
    }
    return res;
  }

  /**
   * Leave-one-out scenarios [first, last) for multiplicative kernels. Returns
   * n x (k * (last - first)); column (b - first) * k + c is scenario b, weight c.
   */
  looMult(
    t: Topology,
    fu: Float64Array,
    fd: Float64Array,
    W: Float64Array,
    k: number,
    barPtr: Int32Array,
    barNode: Int32Array,
    newFu: Float64Array,
    newFd: Float64Array,
    first: number,
    last: number,
    to: boolean,
  ): Float64Array {
    const n = t.parent.length;
    const { outs } = this.call(
      [t.parent, t.order, t.childPtr, t.childIdx, fu, fd, W, barPtr, barNode, newFu, newFd],
      [{ type: 'f64', len: n * k * (last - first) }],
      ([p, o, cp, ci, fup, fdp, w, bp, bn, nfu, nfd], [out]) =>
        this.m._rc_loo_mult(p, o, cp, ci, fup, fdp, w, n, k, bp, bn, nfu, nfd, first, last, to ? 1 : 0, out),
    );
    return outs[0] as Float64Array;
  }

  /** Reach sums for threshold / leptokurtic kernels. */
  bounded(
    t: Topology,
    cu: Float64Array,
    cd: Float64Array,
    cost: Float64Array,
    kernel: number,
    par: Float64Array,
    W: Float64Array,
    k: number,
    needTo: boolean,
    needFrom: boolean,
  ): { sTo: Float64Array; sFrom: Float64Array } {
    const n = t.parent.length;
    const { outs } = this.call(
      [t.parent, t.childPtr, t.childIdx, cu, cd, cost, par, W],
      [
        { type: 'f64', len: needTo ? n * k : 0 },
        { type: 'f64', len: needFrom ? n * k : 0 },
      ],
      ([p, cp, ci, cup, cdp, cp2, parp, w], [sTo, sFrom]) =>
        this.m._rc_bounded(p, cp, ci, cup, cdp, cp2, kernel, parp, w, n, k, needTo ? 1 : 0, needFrom ? 1 : 0, BOUNDED_BLOCK, sTo, sFrom),
    );
    return { sTo: outs[0] as Float64Array, sFrom: outs[1] as Float64Array };
  }
}

let shared: Promise<RcCore> | null = null;
/** One RcCore per realm (main thread, worker or Node process). */
export function getCore(): Promise<RcCore> {
  return (shared ??= RcCore.create());
}
